css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .52); position: relative; }
.loader::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 6%; border-radius: 999px; background: color-mix(in srgb, #000 24%, var(--accent-2)); }
.loader span { position: absolute; bottom: 6%; width: 26%; height: 74%; border-radius: 42% 42% 6px 6px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 28%, var(--accent))); box-shadow: inset calc(var(--loader-size) * .02) 0 calc(var(--loader-size) * .03) rgba(255, 255, 255, .2); }
.loader span:nth-child(1) { left: 4%; animation: swap-right calc(var(--loader-speed) * 2.8) ease-in-out infinite; }
.loader span:nth-child(2) { left: 37%; animation: cup-bob calc(var(--loader-speed) * 2.8) ease-in-out infinite; }
.loader span:nth-child(3) { left: 70%; animation: swap-left calc(var(--loader-speed) * 2.8) ease-in-out infinite; }
@keyframes swap-right { 0%, 10% { transform: translate(0, 0); } 34% { transform: translate(127%, -24%); } 50%, 62% { transform: translate(254%, 0); } 86% { transform: translate(127%, -24%); } 100% { transform: translate(0, 0); } }
@keyframes swap-left { 0%, 10% { transform: translate(0, 0); } 34% { transform: translate(-127%, 24%); } 50%, 62% { transform: translate(-254%, 0); } 86% { transform: translate(-127%, 24%); } 100% { transform: translate(0, 0); } }
@keyframes cup-bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-12%); } }
